}

/* Vùng cấm thuyền quanh công trường dìm đốt hầm (Hầm vượt sông Hàn, z ≈ −1700): chỉ có hiệu lực khi on */
export const boatKeepOut = { on: false, z0: -1760, z1: -1640 };

/* Thuyền du lịch dọc sông Hàn */
const boats: { x: number; z: number; dir: number; speed: number; len: number }[] = [];
let bHull: THREE.InstancedMesh, bCabin: THREE.InstancedMesh, bRoof: THREE.InstancedMesh;
export function buildBoats() {
  const lanesX = [-48, -22, 22, 48];
  for (let i = 0; i < 7; i++) boats.push({ x: lanesX[i % 4], z: -2200 + i * 650, dir: lanesX[i % 4] > 0 ? 1 : -1, speed: 3 + rand() * 2, len: 18 + rand() * 10 });
  const box = new THREE.BoxGeometry(1, 1, 1);
  bHull = new THREE.InstancedMesh(box, MAT.hull, boats.length);
  bCabin = new THREE.InstancedMesh(box, MAT.boatCabin, boats.length);
  bRoof = new THREE.InstancedMesh(box, MAT.boatRoof, boats.length);
  for (const mm of [bHull, bCabin, bRoof]) { mm.frustumCulled = false; mm.castShadow = true; scene.add(mm); }
}
const bq = new THREE.Quaternion(), bBase = new THREE.Vector3(), bM = new THREE.Matrix4(), bS = new THREE.Vector3(), bO = new THREE.Vector3();
export function updateBoats(dt: number, t: number) {
  const q = bq, base = bBase, m = bM, s = bS, o = bO;
  boats.forEach((b, i) => {
    b.z += b.dir * b.speed * dt * (1 - weatherFx.boatAway); if (b.z > 2500) b.z = -2500; if (b.z < -2500) b.z = 2500;   // bão: thuyền chậm dần rồi dừng
    if (boatKeepOut.on && b.z > boatKeepOut.z0 && b.z < boatKeepOut.z1) b.z = b.dir > 0 ? boatKeepOut.z0 : boatKeepOut.z1;
    if (vanished(i, weatherFx.boatAway)) { bHull.setMatrixAt(i, HIDDEN_M); bCabin.setMatrixAt(i, HIDDEN_M); bRoof.setMatrixAt(i, HIDDEN_M); return; }   // về bến: ẩn dần
    q.setFromEuler(_e.set(Math.sin(t * 0.9 + i) * 0.015 * windFx.boatRock, 0, Math.sin(t * 1.1 + i * 2) * 0.02 * windFx.boatRock));   // tròng trành tăng theo gió (mặc định ×1)
    base.set(b.x, 0, b.z);
    bHull.setMatrixAt(i, m.compose(o.set(0, 0.6, 0).applyQuaternion(q).add(base), q, s.set(6.5, 2.6, b.len)));
    bCabin.setMatrixAt(i, m.compose(o.set(0, 3.2, -b.len * 0.05).applyQuaternion(q).add(base), q, s.set(5.4, 2.6, b.len * 0.62)));
    bRoof.setMatrixAt(i, m.compose(o.set(0, 4.7, -b.len * 0.05).applyQuaternion(q).add(base), q, s.set(6.2, 0.35, b.len * 0.7)));
  });
  bHull.instanceMatrix.needsUpdate = bCabin.instanceMatrix.needsUpdate = bRoof.instanceMatrix.needsUpdate = true;
}
import type { SongHanBridge } from './SongHanBridge';

/* [life] xe dừng trước barie, người đi bộ, thuyền du lịch, tàu buồm cao chờ mở luồng */
export function shBuildLife(bridge: SongHanBridge) {
  bridge.traffic = createTraffic(bridge, { seed: 2000, x0: -1500, x1: 1480, busColor: 0x2f7fc1,
    lanes: [{ off: SH.lane, n: 26, speed: 11, bike: 0.6, bus: 0.04 }] });
  // thuyền du lịch nối lộ trình Cầu Rồng – Cầu sông Hàn – Cầu Thuận Phước (giữa các làn thuyền chung)
  bridge.boats = createBoats(bridge, [
    { x: 31, z: 700, dir: -1, speed: 3.4, len: 22, w: 7, h: 2.6, cab: 2.9 },
    { x: 41, z: -900, dir: 1, speed: 3.0, len: 18, w: 6.5, h: 2.5, cab: 2.7 }
  ]);
  // người đi bộ: lề cầu (phần cố định) và lề ven sông Bạch Đằng
  const rnd = rng(2903), list: Walker[] = [], zs = SH.hw - SH.sidewalk / 2 - 0.15;
  for (let i = 0; i < 36; i++) {
    const west = i % 2 === 0, lo = west ? -285 : SH.fixedStart + 8, hi = west ? -SH.fixedStart - 8 : 285;
    list.push({ x: lerp(lo, hi, rnd()), z: (rnd() < 0.5 ? -1 : 1) * zs, lo, hi, dir: rnd() < 0.5 ? -1 : 1, speed: 1 + rnd() * 0.5, profile: (x) => shRoadY(x) + 0.25 });
  }
  for (let i = 0; i < 40; i++) list.push({ x: -276 + (rnd() - 0.5) * 18, z: lerp(-420, 420, rnd()), lo: -420, hi: 420, dir: rnd() < 0.5 ? -1 : 1,
    speed: 0.9 + rnd() * 0.5, axis: 'z', profile: () => CONFIG.landY + 0.05 });
  bridge.people = createPeople(bridge, list, bridge.mats.person, 'sh-people', rnd);
  // tàu buồm cao: cột buồm cao hơn tĩnh không, chỉ qua được khi cầu mở (luồng phía Tây)
  const ship = new THREE.Group(); ship.name = 'sh-tall-ship';
  const hull = new THREE.Mesh(new THREE.BoxGeometry(7, 3, 30).translate(0, 1.0, 0), MAT.hull);
  const house = new THREE.Mesh(new THREE.BoxGeometry(5, 2.4, 9).translate(0, 3.7, -6), MAT.boatCabin);
  const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.3, 19, 8).translate(0, 11.5, 2), MAT.lampPole);
  const sailShape = new THREE.Shape([new THREE.Vector2(0, 0), new THREE.Vector2(0, 16), new THREE.Vector2(-9, 0)]);
  const sail = new THREE.Mesh(new THREE.ShapeGeometry(sailShape).rotateY(Math.PI / 2).translate(0, 4, 2.6), bridge.mats.sail);
  ship.add(hull, house, mast, sail);
  for (const o of [hull, house, mast, sail]) o.castShadow = true;
  ship.position.set(-36, 0, -260);
  bridge.life.add(ship);
  bridge.ship = { obj: ship, z: -260, target: -260, dir: 1, speed: 4.5 };
}

/* Xe: như hệ chung, nhưng khi không cho vào nhịp quay thì xếp hàng trước barie */
const before: BridgeVehicle[] = [];          // mảng tạm dùng lại (D-018)
    { off: TP.median / 2 + TP.laneWidth * 1.5, n: 30, speed: 11, bike: 0.6 }     // làn ngoài, nhiều xe máy
  ] });
}
export function tpBuildBoats(bridge: ThuanPhuocBridge) {
  // tàu cá, tàu du lịch và một tàu hàng nhỏ đi qua nhịp chính (tĩnh không 27 m)
  bridge.boats = createBoats(bridge, [
    { x: -70, z: 600, dir: -1, speed: 4.2, len: 22, w: 6.5, h: 2.6, cab: 2.6 },
    { x: 30, z: -500, dir: 1, speed: 3.4, len: 18, w: 6, h: 2.4, cab: 2.4 },
    { x: 110, z: 200, dir: -1, speed: 2.6, len: 46, w: 10, h: 4.2, cab: 7.5 }
  ]);
}
  // 2 làn trong mỗi chiều dùng hệ xe chung của scene (PATHS.ttl); làn ngoài (nhiều xe máy) ở đây
